it('makeResult handles missing documentId gracefully', () => {
  const ms = new MiniSearch({ fields: ['text'] });
  ms.add({ id: 1, text: 'test' });
  // Manually corrupt internal state or test with invalid docId
  const rawResult = { score: 10, terms: ['test'], match: { text: ['test'] } };
  const result = ms.makeResult(999, rawResult);
  expect(result.id).toBeUndefined();
});

it('makeResult handles missing storedFields', () => {
  const ms = new MiniSearch({ fields: ['text'], storeFields: ['category'] });
  ms.add({ id: 1, text: 'test', category: 'doc' });
  const rawResult = { score: 10, terms: ['test'], match: { text: ['test'] } };
  // Test with docId that has no stored fields
  const result = ms.makeResult(1, rawResult);
  expect(result).toHaveProperty('score');
  expect(result).toHaveProperty('id');
});

it('makeResult calculates quality correctly with empty terms', () => {
  const ms = new MiniSearch({ fields: ['text'] });
  ms.add({ id: 1, text: 'test' });
  const rawResult = { score: 10, terms: [], match: { text: ['test'] } };
  const result = ms.makeResult(1, rawResult);
  expect(result.score).toBe(10); // quality defaults to 1
  expect(result.queryTerms).toEqual([]);
});

it('applies QueryCombination filter with AND combineWith', () => {
  const ms = new MiniSearch({ fields: ['text'], storeFields: ['category'] });
  ms.add({ id: 1, text: 'alpha beta', category: 'A' });
  ms.add({ id: 2, text: 'alpha gamma', category: 'B' });
  const results = ms.search({
    queries: [{ queries: ['alpha'] }, { queries: ['beta'] }],
    combineWith: 'AND',
    filter: (r) => r.category === 'A'
  });
  expect(results).toHaveLength(1);
  expect(results[0].id).toBe(1);
});

it('applies QueryCombination filter with AND_NOT combineWith', () => {
