});

it('handles filter that rejects all results at QueryCombination level', () => {
  const ms = new MiniSearch({ fields: ['text'], storeFields: ['category'] });
  ms.add({ id: 1, text: 'test', category: 'A' });
  ms.add({ id: 2, text: 'test', category: 'B' });
  const results = ms.search({
    queries: [{ queries: ['test'] }],
    filter: (r) => r.category === 'C' // no matches
  });
  expect(results).toEqual([]);
});

it('handles undefined/null filter at QueryCombination level', () => {
  const ms = new MiniSearch({ fields: ['text'] });
  ms.add({ id: 1, text: 'test' });
  const results1 = ms.search({ queries: [{ queries: ['test'] }], filter: null });
  const results2 = ms.search({ queries: [{ queries: ['test'] }], filter: undefined });
  expect(results1.length).toBeGreaterThan(0);
  expect(results2.length).toBeGreaterThan(0);
});

it('applies both sub-query and QueryCombination-level filters correctly', () => {
  const ms = new MiniSearch({ fields: ['text'], storeFields: ['category', 'status'] });
  ms.add({ id: 1, text: 'test', category: 'A', status: 'active' });
  ms.add({ id: 2, text: 'test', category: 'B', status: 'active' });
  ms.add({ id: 3, text: 'demo', category: 'A', status: 'inactive' });
  const results = ms.search({
    queries: [
      { queries: ['test'], filter: (r) => r.category === 'A' },
      { queries: ['demo'], filter: (r) => r.category === 'A' }
    ],
    filter: (r) => r.status === 'active'
  });
  expect(results).toHaveLength(1);
  expect(results[0].id).toBe(1);
});

it('handles filter exceptions gracefully', () => {
  const ms = new MiniSearch({ fields: ['text'] });
  ms.add({ id: 1, text: 'test' });
  const badFilter = (r) => { throw new Error('Filter error'); };
  expect(() => {
    ms.search({ queries: [{ queries: ['test'] }], filter: badFilter });
  }).toThrow('Filter error');
});

it('handles empty combined results before filter application', () => {
  const ms = new MiniSearch({ fields: ['text'] });
  ms.add({ id: 1, text: 'test' });
  const results = ms.search({
    queries: [{ queries: ['nonexistent'] }],
    filter: (r) => r.score > 0
  });
  expect(results).toEqual([]);
});

it('makeResult handles various match object structures', () => {
  const ms = new MiniSearch({ fields: ['text', 'title'] });
  ms.add({ id: 1, text: 'test', title: 'sample' });
  const rawResult = { score: 10, terms: ['test'], match: { text: ['test'], title: [] } };
  const result = ms.makeResult(1, rawResult);
  expect(result.terms).toEqual(['text', 'title']);
  expect(result.match).toEqual({ text: ['test'], title: [] });
});

it('filter cannot mutate result objects', () => {
  const ms = new MiniSearch({ fields: ['text'], storeFields: ['category'] });
  ms.add({ id: 1, text: 'test', category: 'A' });
  const results = ms.search({
    queries: [{ queries: ['test'] }],
    filter: (r) => { r.category = 'MODIFIED'; return true; }
  });
  expect(results[0].category).toBe('A'); // should remain unchanged
});

