private makeResult (docId: number, { score, terms, match }: RawResultValue): SearchResult {
  const quality = terms.length || 1
  const documentId = this._documentIds.get(docId)
  if (documentId === undefined) {
    throw new Error(`Document ID ${docId} not found in index`)
  }

  const result: SearchResult = {
    id: documentId,
    score: score * quality,
    terms: Object.keys(match),
    queryTerms: terms,
    match
  }

  const storedFields = this._storedFields.get(docId)
  if (storedFields !== undefined) {
    Object.assign(result, storedFields)
  }

  return result
}

